// Fisher-Yates array shuffler to randomize questions
function shuffleArray(array) {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// @route   GET /api/questions/seed
// @desc    Seed questions into database (run once)
router.get('/seed', async (req, res) => {
  try {
    await Question.deleteMany({});
    await Question.insertMany(sampleQuestions);
    res.json({ success: true, message: `Seeded ${sampleQuestions.length} questions successfully across 7 categories!` });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

// @route   GET /api/questions/:category
// @desc    Get 5 randomized questions by category
router.get('/:category', protect, async (req, res) => {
  try {
    const { category } = req.params;
    const validCategories = ['Python', 'Java', 'C++', 'DSA', 'DBMS', 'HR', 'FULLSTACK'];

    const normalize = s => (s || '').replace(/[\s-_]+/g, '').toLowerCase();
    const matchedCat = validCategories.find(c => normalize(c) === normalize(category));
    if (!matchedCat) {
      return res.status(400).json({ success: false, message: 'Invalid category.' });
    }

    const mongoose = require('mongoose');
    let pool = [];

    if (mongoose.connection.readyState === 1) {
      try {
        pool = await Question.find({ category: matchedCat });
      } catch (dbErr) {
        console.warn('DB query failed, falling back to static questions:', dbErr.message);
      }
    }

    // If no questions in DB or DB offline, use static pool
    if (!pool || pool.length === 0) {
      pool = sampleQuestions.filter(q => normalize(q.category) === normalize(matchedCat));
    }

    // Shuffle and pick 5 random questions
    const shuffled = shuffleArray(pool);
    const selected = shuffled.slice(0, 5).map((q, idx) => {
      let options = q.options ? [...q.options] : undefined;
      let correctOption = q.correctOption;
      if (options && correctOption) {
        const letters = ['A', 'B', 'C', 'D'];
        const paired = options.map((opt, i) => ({ opt, letter: letters[i] }));
        const shuffledPairs = shuffleArray(paired);
        const correctIndex = shuffledPairs.findIndex(pair => pair.letter === correctOption);
        options = shuffledPairs.map(pair => pair.opt);
        correctOption = correctIndex >= 0 ? letters[correctIndex] : correctOption;
      }
      return {
        ...((q.toObject && typeof q.toObject === 'function') ? q.toObject() : q),
        order: idx + 1,
        maxScore: q.maxScore || 10,
        ...(options && { options }),
        ...(correctOption && { correctOption })
      };
    });

    res.json({
      success: true,
      questions: selected,
      totalInBank: pool.length,
      source: mongoose.connection.readyState === 1 ? 'database' : 'static'
    });
  } catch (error) {
    // Ultimate fallback: always return 5 random questions so user is never blocked
    const normalize = s => (s || '').replace(/[\s-_]+/g, '').toLowerCase();
    const fallbackPool = sampleQuestions.filter(q => normalize(q.category) === normalize(req.params.category));
    const shuffled = shuffleArray(fallbackPool.length > 0 ? fallbackPool : sampleQuestions);
    const selected = shuffled.slice(0, 5).map((q, idx) => {
      let options = q.options ? [...q.options] : undefined;
      let correctOption = q.correctOption;
      if (options && correctOption) {
        const letters = ['A', 'B', 'C', 'D'];
        const paired = options.map((opt, i) => ({ opt, letter: letters[i] }));
        const shuffledPairs = shuffleArray(paired);
        const correctIndex = shuffledPairs.findIndex(pair => pair.letter === correctOption);
        options = shuffledPairs.map(pair => pair.opt);
        correctOption = correctIndex >= 0 ? letters[correctIndex] : correctOption;
      }
      return {
        ...((q.toObject && typeof q.toObject === 'function') ? q.toObject() : q),
        order: idx + 1,
        maxScore: q.maxScore || 10,
        ...(options && { options }),
        ...(correctOption && { correctOption })
      };
    });
    res.json({ success: true, questions: selected, source: 'fallback' });
  }
});

module.exports = router;
